import numpy as np


def pad_same(x, k_len, mode):
    x = np.asarray(x, dtype=float)
    left = (k_len - 1) // 2
    right = k_len - 1 - left
    if mode == 'zero':
        return np.concatenate([np.zeros(left), x, np.zeros(right)])
    if mode == 'edge':
        return np.concatenate([np.full(left, x[0]), x, np.full(right, x[-1])])
    raise ValueError(f'unknown mode {mode!r}')

