def pad_same(x, k_len, mode):
    x = np.asarray(x, dtype=float)
    left = (k_len - 1) // 2
    right = k_len - 1 - left
    if mode in ('zero', 'edge'):
        return np.concatenate([np.zeros(left), x, np.zeros(right)])
